//! What the project brings itself, so the engine does not overwrite it: the real `next` package (the
//! same folder also runs with `next dev`, e.g. the `build/nextjs` app generated by comx) and its own
//! `core` module (`core/index.ts`, mapped by the project's tsconfig).

use std::path::{Path, PathBuf};

/// `next` is installed from npm (not the stub package earlier engine versions wrote)
pub fn has_real_next(root: &Path) -> bool {
    crate::store::packages_dir(root).join("next/dist").is_dir()
}

/// The project's own `core` module, which `import ... from "core"` resolves to instead of `.nata/core.ts`.
/// Only when the project says so (a comx build, or a tsconfig mapping `core` into `core/`): an app with a
/// `core/` folder of its own (helpers, no `db`) and `core` mapped to `.nata/core.ts` failed with
/// "core/index.ts does not provide an export named 'db'"
pub fn project_core(root: &Path) -> Option<PathBuf> {
    let file = ["core/index.ts", "core/index.tsx", "core/index.js"].iter().map(|p| root.join(p)).find(|p| p.is_file())?;
    (is_comx_build(root) || maps_core_to_project(root)).then_some(file)
}

/// tsconfig.json's `paths.core` points at the project's `core/` (not the engine's `.nata/core.ts`)
fn maps_core_to_project(root: &Path) -> bool {
    let Ok(text) = std::fs::read_to_string(root.join("tsconfig.json")) else { return false };
    let clean = crate::resolver::tsconfig::TsConfig::strip_comments(&text);
    let Ok(json) = serde_json::from_str::<serde_json::Value>(&clean) else { return false };
    json["compilerOptions"]["paths"]["core"].as_array().is_some_and(|targets| {
        targets.iter().filter_map(|t| t.as_str()).any(|t| {
            let t = t.trim_start_matches("./");
            t == "core" || t.starts_with("core/")
        })
    })
}

const CORE_TSCONFIG_MARK: &str = "// Written by com: inside core/, \"core\" is the NATA platform (.nata/core.ts)";

/// Files under the project's own `core/` (the cloud overlay: `core/db.ts` does `import { db, sql } from "core"`)
/// mean the platform, not the project's core: through the root tsconfig they imported `core/index.ts`
/// itself, a cycle (index → db → index) that failed with "does not provide an export named 'db'".
/// Bun takes `paths` from the nearest tsconfig, so `core/tsconfig.json` repeats the root's paths with `core`
/// pointing at the engine. A `core/tsconfig.json` the project wrote itself is left alone.
pub fn write_core_tsconfig(root: &Path) {
    if project_core(root).is_none() {
        return;
    }
    let target = root.join("core/tsconfig.json");
    if let Ok(existing) = std::fs::read_to_string(&target) {
        if !existing.starts_with(CORE_TSCONFIG_MARK) {
            return;
        }
    }
    let parent: serde_json::Value = std::fs::read_to_string(root.join("tsconfig.json"))
        .ok()
        .and_then(|t| serde_json::from_str(&crate::resolver::tsconfig::TsConfig::strip_comments(&t)).ok())
        .unwrap_or_default();
    let options = &parent["compilerOptions"];
    let base = match options["baseUrl"].as_str().map(|b| b.trim_start_matches("./").trim_end_matches('/')) {
        None | Some("") | Some(".") => "..".to_string(),
        Some(b) => format!("../{b}"),
    };
    let mut paths = options["paths"].as_object().cloned().unwrap_or_default();
    // Relative to baseUrl, like the root's own targets (which keep their meaning under the new baseUrl)
    let nata_from_base = if base == ".." { "./.nata/core.ts".to_string() } else {
        let depth = base.trim_start_matches("../").split('/').filter(|s| !s.is_empty()).count();
        format!("{}.nata/core.ts", "../".repeat(depth))
    };
    paths.insert("core".into(), serde_json::json!([nata_from_base]));
    let json = serde_json::json!({
        "extends": "../tsconfig.json",
        "compilerOptions": { "baseUrl": base, "paths": paths },
    });
    let text = format!("{CORE_TSCONFIG_MARK}\n{}\n", serde_json::to_string_pretty(&json).unwrap_or_default());
    crate::next_shims::write_if_changed(target, text);
}

/// A Next.js app generated by comx (`<workspace>/build/nextjs`): backend modules behind an RPC server
pub fn is_comx_build(root: &Path) -> bool {
    root.join("core/rpc/proxy-dispatcher.ts").is_file() && root.join("config/plugins.json").is_file()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_real_next_core_and_comx_build() {
        let dir = std::env::temp_dir().join(format!("nata_project_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let root = dir.as_path();
        assert!(!has_real_next(root));
        assert!(project_core(root).is_none());
        assert!(!is_comx_build(root));

        std::fs::create_dir_all(root.join("node_modules/next/dist")).unwrap();
        std::fs::create_dir_all(root.join("core/rpc")).unwrap();
        std::fs::create_dir_all(root.join("config")).unwrap();
        std::fs::write(root.join("core/index.ts"), "export {};").unwrap();
        std::fs::write(root.join("core/rpc/proxy-dispatcher.ts"), "export {};").unwrap();
        std::fs::write(root.join("config/plugins.json"), "[]").unwrap();

        assert!(has_real_next(root));
        assert_eq!(project_core(root), Some(root.join("core/index.ts")));
        assert!(is_comx_build(root));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn own_core_folder_is_used_only_when_mapped() {
        let dir = std::env::temp_dir().join(format!("nata_project_core_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("core")).unwrap();
        let root = dir.as_path();
        std::fs::write(root.join("core/index.ts"), "export const helpers = {};").unwrap();
        // No tsconfig, or `core` mapped to the engine: the framework's core (with db)
        assert!(project_core(root).is_none());
        std::fs::write(root.join("tsconfig.json"), r#"{"compilerOptions":{"paths":{"core":["./.nata/core.ts"]}}}"#).unwrap();
        assert!(project_core(root).is_none());
        // Mapped into core/ (with a comment, as tsconfig allows): the project's own
        std::fs::write(root.join("tsconfig.json"), "{\n // own core\n \"compilerOptions\":{\"paths\":{\"core\":[\"./core/index.ts\"]}}}").unwrap();
        assert_eq!(project_core(root), Some(root.join("core/index.ts")));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn core_folder_gets_the_platform_core() {
        let dir = std::env::temp_dir().join(format!("nata_core_tsconfig_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("core")).unwrap();
        let root = dir.as_path();
        std::fs::write(root.join("core/index.ts"), "export * from \"./db\";").unwrap();
        let tsconfig = r#"{"compilerOptions":{"baseUrl":".","paths":{"@/*":["./*"],"core":["./core/index.ts"]}}}"#;
        std::fs::write(root.join("tsconfig.json"), tsconfig).unwrap();

        write_core_tsconfig(root);
        let text = std::fs::read_to_string(root.join("core/tsconfig.json")).unwrap();
        let json: serde_json::Value =
            serde_json::from_str(&crate::resolver::tsconfig::TsConfig::strip_comments(&text)).unwrap();
        assert_eq!(json["compilerOptions"]["baseUrl"], "..");
        assert_eq!(json["compilerOptions"]["paths"]["core"], serde_json::json!(["./.nata/core.ts"]));
        assert_eq!(json["compilerOptions"]["paths"]["@/*"], serde_json::json!(["./*"]));
        // The root's own mapping is untouched
        assert_eq!(std::fs::read_to_string(root.join("tsconfig.json")).unwrap(), tsconfig);

        // The project's own core/tsconfig.json is never replaced
        std::fs::write(root.join("core/tsconfig.json"), "{}").unwrap();
        write_core_tsconfig(root);
        assert_eq!(std::fs::read_to_string(root.join("core/tsconfig.json")).unwrap(), "{}");
        let _ = std::fs::remove_dir_all(&dir);
    }
}
